{"Content":"@import "tailwindcss";
@import "leaflet/dist/leaflet.css";

/* Custom scrollbars for dashboard tables and sidebars */
::-webkit-scrollbar {
  width: 6px;
  height: 6px;
}

::-webkit-scrollbar-track {
  background: transparent;
}

::-webkit-scrollbar-thumb {
  background: #cbd5e1;
  border-radius: 9999px;
}

::-webkit-scrollbar-thumb:hover {
  background: #94a3b8;
}

/* Ensure Leaflet container stays within bounds and has proper z-index */
.leaflet-container {
  width: 100%;
  height: 100%;
  z-index: 10;
  font-family: inherit;
}

/* Custom pulse animations for live status rings */
@keyframes ping-slow {
  75%, 100% {
    transform: scale(2);
    opacity: 0;
  }
}

.animate-ping-slow {
  animation: ping-slow 2.5s cubic-bezier(0, 0, 0.2, 1) infinite;
}
