{"Content":"import React from 'react';
import { Truck, Navigation, Clock, WifiOff, AlertOctagon, ChevronRight } from 'lucide-react';
import { FleetStats, VehicleStatus } from '../types/fleet';

interface StatsOverviewProps {
  stats: FleetStats;
  selectedFilter: VehicleStatus | 'all';
  onSelectFilter: (filter: VehicleStatus | 'all') => void;
}

export const StatsOverview: React.FC<StatsOverviewProps> = ({
  stats,
  selectedFilter,
  onSelectFilter,
}) => {
  const cards = [
    {
      id: 'all' as const,
      label: 'Total Fleet',
      count: stats.total,
      sublabel: 'All monitored units',
      icon: Truck,
      color: 'blue',
      cardBg: 'bg-white',
      borderActive: 'border-blue-500 ring-2 ring-blue-500/20',
      badgeColor: 'bg-blue-50 text-blue-700 border-blue-200',
      iconBg: 'bg-blue-100 text-blue-700',
    },
    {
      id: 'moving' as const,
      label: 'Moving & In-Transit',
      count: stats.moving,
      sublabel: 'Active on road',
      icon: Navigation,
      color: 'emerald',
      cardBg: 'bg-white',
      borderActive: 'border-emerald-500 ring-2 ring-emerald-500/20',
      badgeColor: 'bg-emerald-50 text-emerald-700 border-emerald-200',
      iconBg: 'bg-emerald-100 text-emerald-700',
    },
    {
      id: 'idle' as const,
      label: 'Idle & Standby',
      count: stats.idle,
      sublabel: 'Stationary / engine off',
      icon: Clock,
      color: 'amber',
      cardBg: 'bg-white',
      borderActive: 'border-amber-500 ring-2 ring-amber-500/20',
      badgeColor: 'bg-amber-50 text-amber-700 border-amber-200',
      iconBg: 'bg-amber-100 text-amber-700',
    },
    {
      id: 'offline' as const,
      label: 'Offline / No Signal',
      count: stats.offline,
      sublabel: 'Heartbeat timeout',
      icon: WifiOff,
      color: 'slate',
      cardBg: 'bg-white',
      borderActive: 'border-slate-500 ring-2 ring-slate-500/20',
      badgeColor: 'bg-slate-100 text-slate-700 border-slate-300',
      iconBg: 'bg-slate-200 text-slate-700',
    },
    {
      id: 'alert' as const,
      label: 'Attention Required',
      count: stats.attentionRequired,
      sublabel: 'Critical sensor alerts',
      icon: AlertOctagon,
      color: 'rose',
      cardBg: 'bg-white',
      borderActive: 'border-rose-500 ring-2 ring-rose-500/20',
      badgeColor: 'bg-rose-50 text-rose-700 border-rose-200',
      iconBg: 'bg-rose-100 text-rose-700',
    },
  ];

  return (
    <section aria-label="Fleet Summary Metrics">
      <div className="grid grid-cols-2 sm:grid-cols-3 lg:grid-cols-5 gap-3.5">
        {cards.map((card) => {
          const Icon = card.icon;
          const isSelected = selectedFilter === card.id;

          return (
            <button
              key={card.id}
              onClick={() => onSelectFilter(card.id)}
              className={`text-left p-4 rounded-xl border transition-all duration-200 shadow-sm cursor-pointer group hover:shadow-md ${
                isSelected
                  ? `${card.borderActive} bg-slate-50/90`
                  : 'border-slate-200/90 bg-white hover:border-slate-300'
              }`}
            >
              <div className="flex items-center justify-between mb-2">
                <div className={`p-2 rounded-lg ${card.iconBg} transition-transform group-hover:scale-105`}>
                  <Icon className="h-4 w-4" />
                </div>
                <span className="text-[11px] font-semibold text-slate-400 group-hover:text-slate-600 flex items-center">
                  Filter
                  <ChevronRight className="h-3 w-3 ml-0.5 opacity-60 group-hover:translate-x-0.5 transition-transform" />
                </span>
              </div>

              <div className="flex items-baseline justify-between mt-1">
                <span className="text-2xl font-bold tracking-tight text-slate-900">
                  {card.count}
                </span>
                <span className={`text-[10px] font-bold px-1.5 py-0.5 rounded border uppercase ${card.badgeColor}`}>
                  {card.id}
                </span>
              </div>

              <p className="text-xs font-semibold text-slate-700 mt-1 truncate">
                {card.label}
              </p>
              <p className="text-[11px] text-slate-400 mt-0.5 truncate">
                {card.sublabel}
              </p>
            </button>
          );
        })}
      </div>
    </section>
  );
};
