{"Content":"import React, { useState, useEffect } from 'react';
import { Sidebar, NavTab } from './components/Sidebar';
import { Navbar } from './components/Navbar';
import { StatsOverview } from './components/StatsOverview';
import { FleetMap } from './components/FleetMap';
import { VehicleTable } from './components/VehicleTable';
import { VehicleDetailsPanel } from './components/VehicleDetailsModal';
import { TripsList } from './components/TripsList';
import { AlertQueue } from './components/AlertQueue';
import {
  INITIAL_VEHICLES,
  INITIAL_ALERTS,
  INITIAL_TRIPS,
} from './data/mockFleetData';
import { Vehicle, FleetAlert, Trip, VehicleStatus, FleetStats } from './types/fleet';
import { AlertTriangle, MapPin, Truck, Route, Info } from 'lucide-react';

export function App() {
  const [activeTab, setActiveTab] = useState<NavTab>('overview');
  const [vehicles, setVehicles] = useState<Vehicle[]>(INITIAL_VEHICLES);
  const [alerts, setAlerts] = useState<FleetAlert[]>(INITIAL_ALERTS);
  const [trips] = useState<Trip[]>(INITIAL_TRIPS);
  const [selectedVehicle, setSelectedVehicle] = useState<Vehicle | null>(null);
  const [statusFilter, setStatusFilter] = useState<VehicleStatus | 'all'>('all');
  const [isSimulating, setIsSimulating] = useState<boolean>(true);
  const [isOpenMobile, setIsOpenMobile] = useState<boolean>(false);
  const [lastUpdated, setLastUpdated] = useState<string>('Live');

  // Compute live fleet stats
  const fleetStats: FleetStats = {
    total: vehicles.length,
    moving: vehicles.filter((v) => v.status === 'moving').length,
    idle: vehicles.filter((v) => v.status === 'idle').length,
    offline: vehicles.filter((v) => v.status === 'offline').length,
    attentionRequired: alerts.filter((a) => !a.isAcknowledged).length,
  };

  // Periodic Telemetry Simulation (Kochi Hub live pulse)
  useEffect(() => {
    if (!isSimulating) return;

    const interval = setInterval(() => {
      setVehicles((prev) =>
        prev.map((v) => {
          if (v.status === 'moving') {
            // Small positional drift along road corridors
            const latDelta = (Math.random() - 0.48) * 0.0006;
            const lngDelta = (Math.random() - 0.48) * 0.0006;
            const speedFluctuation = Math.floor((Math.random() - 0.5) * 4);
            const newSpeed = Math.max(20, Math.min(65, v.telemetry.speed + speedFluctuation));

            return {
              ...v,
              location: {
                ...v.location,
                lat: Number((v.location.lat + latDelta).toFixed(5)),
                lng: Number((v.location.lng + lngDelta).toFixed(5)),
                lastPing: 'Just now',
              },
              telemetry: {
                ...v.telemetry,
                speed: newSpeed,
              },
            };
          }
          return v;
        })
      );

      const now = new Date();
      setLastUpdated(now.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit' }));
    }, 4000);

    return () => clearInterval(interval);
  }, [isSimulating]);

  // Handle vehicle selection by ID from alerts or trips
  const handleSelectVehicleById = (vehicleId: string) => {
    const found = vehicles.find((v) => v.id === vehicleId);
    if (found) {
      setSelectedVehicle(found);
    }
  };

  // Simulate an instant manual ping for a specific vehicle
  const handleSimulatePing = (vehicleId: string) => {
    setVehicles((prev) =>
      prev.map((v) => {
        if (v.id === vehicleId) {
          const speedBoost = v.status === 'moving' ? Math.floor(Math.random() * 6) - 3 : 0;
          return {
            ...v,
            location: {
              ...v.location,
              lastPing: '1s ago (manual poll)',
            },
            telemetry: {
              ...v.telemetry,
              speed: Math.max(0, v.telemetry.speed + speedBoost),
            },
          };
        }
        return v;
      })
    );
  };

  // Toggle alert acknowledgment
  const handleAcknowledgeAlert = (alertId: string) => {
    setAlerts((prev) =>
      prev.map((a) =>
        a.id === alertId ? { ...a, isAcknowledged: !a.isAcknowledged } : a
      )
    );
  };

  // Keep selectedVehicle sync'd with live updates
  const activeSelectedVehicle = selectedVehicle
    ? vehicles.find((v) => v.id === selectedVehicle.id) || selectedVehicle
    : null;

  return (
    <div className="flex h-screen w-full bg-slate-50 text-slate-800 font-sans overflow-hidden antialiased">
      {/* Dark Navy Sidebar */}
      <Sidebar
        activeTab={activeTab}
        onTabChange={(tab) => {
          setActiveTab(tab);
          // If moving between dedicated tabs, adjust filter if needed
          if (tab === 'vehicles' && statusFilter === 'all') {
            // Keep filter
          }
        }}
        isOpenMobile={isOpenMobile}
        onCloseMobile={() => setIsOpenMobile(false)}
        vehicleCount={vehicles.length}
        activeTripsCount={trips.filter((t) => t.status === 'in_progress').length}
        unreadAlertsCount={alerts.filter((a) => !a.isAcknowledged).length}
      />

      {/* Main Operations Content Area */}
      <div className="flex flex-1 flex-col overflow-hidden">
        {/* Sticky Top Navbar */}
        <Navbar
          activeTab={activeTab}
          onOpenMobileMenu={() => setIsOpenMobile(true)}
          isSimulating={isSimulating}
          onToggleSimulation={() => setIsSimulating(!isSimulating)}
          onRefreshData={() => {
            const now = new Date();
            setLastUpdated(now.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit' }));
          }}
          lastUpdated={lastUpdated}
        />

        {/* Scrollable Main Workspace */}
        <main className="flex-1 overflow-y-auto px-4 sm:px-6 py-6 space-y-6">
          {/* Overview Tab (Default Full Operations Command View) */}
          {activeTab === 'overview' && (
            <>
              {/* Summary Metrics Cards */}
              <StatsOverview
                stats={fleetStats}
                selectedFilter={statusFilter}
                onSelectFilter={(newFilter) => setStatusFilter(newFilter)}
              />

              {/* Map & Live Operations Grid */}
              <div className="space-y-4">
                <div className="flex items-center justify-between">
                  <div className="flex items-center space-x-2">
                    <MapPin className="h-4 w-4 text-blue-600" />
                    <h2 className="text-sm font-bold uppercase tracking-wider text-slate-700">
                      Live Telematics Geospatial Map
                    </h2>
                  </div>
                  <span className="text-xs text-slate-500 font-medium hidden sm:inline">
                    Click any marker or table row to view live IoT diagnostics
                  </span>
                </div>

                <FleetMap
                  vehicles={vehicles}
                  selectedVehicle={activeSelectedVehicle}
                  onSelectVehicle={(v) => setSelectedVehicle(v)}
                  statusFilter={statusFilter}
                  onFilterChange={(st) => setStatusFilter(st)}
                />
              </div>

              {/* Vehicle Table */}
              <VehicleTable
                vehicles={vehicles}
                selectedVehicle={activeSelectedVehicle}
                onSelectVehicle={(v) => setSelectedVehicle(v)}
                statusFilter={statusFilter}
                onStatusFilterChange={(st) => setStatusFilter(st)}
              />

              {/* Lower Dual Grid: Recent Trips & Operational Alert Queue */}
              <div className="grid grid-cols-1 xl:grid-cols-2 gap-6">
                <AlertQueue
                  alerts={alerts}
                  onAcknowledgeAlert={handleAcknowledgeAlert}
                  onSelectVehicleById={handleSelectVehicleById}
                />
                <TripsList
                  trips={trips}
                  vehicles={vehicles}
                  onSelectVehicleById={handleSelectVehicleById}
                />
              </div>
            </>
          )}

          {/* Vehicles Tab: Focused Asset Table & Map */}
          {activeTab === 'vehicles' && (
            <div className="space-y-6">
              <StatsOverview
                stats={fleetStats}
                selectedFilter={statusFilter}
                onSelectFilter={(newFilter) => setStatusFilter(newFilter)}
              />

              <VehicleTable
                vehicles={vehicles}
                selectedVehicle={activeSelectedVehicle}
                onSelectVehicle={(v) => setSelectedVehicle(v)}
                statusFilter={statusFilter}
                onStatusFilterChange={(st) => setStatusFilter(st)}
              />

              <div className="bg-white p-5 rounded-2xl border border-slate-200/90 shadow-sm space-y-3">
                <h3 className="text-sm font-bold text-slate-800">
                  Regional Asset Distribution (Kochi Hub)
                </h3>
                <FleetMap
                  vehicles={vehicles}
                  selectedVehicle={activeSelectedVehicle}
                  onSelectVehicle={(v) => setSelectedVehicle(v)}
                  statusFilter={statusFilter}
                  onFilterChange={(st) => setStatusFilter(st)}
                />
              </div>
            </div>
          )}

          {/* Trips Tab: Dedicated Dispatch & Transit corridors */}
          {activeTab === 'trips' && (
            <div className="space-y-6">
              <TripsList
                trips={trips}
                vehicles={vehicles}
                onSelectVehicleById={handleSelectVehicleById}
              />
            </div>
          )}

          {/* Alerts Tab: Operational Alert Triage Queue */}
          {activeTab === 'alerts' && (
            <div className="space-y-6">
              <AlertQueue
                alerts={alerts}
                onAcknowledgeAlert={handleAcknowledgeAlert}
                onSelectVehicleById={handleSelectVehicleById}
              />
            </div>
          )}
        </main>
      </div>

      {/* Slide-out Vehicle Diagnostics Details Panel */}
      {activeSelectedVehicle && (
        <VehicleDetailsPanel
          vehicle={activeSelectedVehicle}
          onClose={() => setSelectedVehicle(null)}
          onCenterOnMap={(v) => {
            // Re-assert selection to trigger map center
            setSelectedVehicle({ ...v });
          }}
          onSimulatePing={handleSimulatePing}
        />
      )}
    </div>
  );
}

export default App;
